namespace MediaReviewer {
    public sealed class IncompleteOriginalExportException:IOException {
        internal const string Prefix="Export stopped; the incomplete chosen output could not be removed safely. Inspect ";
        public IncompleteOriginalExportException(string path,Exception inner):base(Prefix+path,inner){}
    }
    internal sealed class PackageHeader {
        public int Version,Count;public string PackageId,WorkspaceId,OperationId,PayloadHash,CreatedUtc;public VaultDescriptor Vault;
        public PackageHeader(){}
        internal void Validate(){if(Version!=1 || Count<1 || Count>200 || PackageId==null || PackageId.Length!=32 || String.IsNullOrEmpty(WorkspaceId) || WorkspaceId.Length>4096 || String.IsNullOrEmpty(OperationId) || OperationId.Length>100 || !PackageFormat.IsHash(PayloadHash) || CreatedUtc==null || CreatedUtc.Length>64 || Vault==null)throw new InvalidDataException("Unsupported or damaged protected package header");Vault.Validate();}
    }
    internal sealed class PackageRecord {
        public long Size;public int Version,ChunkSize,ChunkCount;public bool Preview;public byte[] IdentityIv;public string IdentityCipher;
        internal long GroupId;internal string Key,Hash,CaptureId;
        public PackageRecord(){}
        internal long FirstChunk;internal PackageFrame Metadata,Poster;
        internal void ValidateShape(){if(Size<0 || Size>5000000000L || Version<1 || Version>3 || IdentityIv==null || IdentityIv.Length!=12 || IdentityCipher==null || IdentityCipher.Length<24 || IdentityCipher.Length>32768 || (Version==1 ? ChunkCount!=1 || ChunkSize!=0 || Preview : ChunkSize<1 || ChunkSize>EvidenceFormat.ChunkSize || ChunkCount!=(Size+ChunkSize-1)/ChunkSize))throw new InvalidDataException("Unsupported protected original descriptor");}
        void ValidateIdentity(){if(GroupId<1 || String.IsNullOrEmpty(Key) || Key.Length>4096 || !PackageFormat.IsHash(Hash) || Version==3 && (CaptureId==null || CaptureId.Length!=32))throw new InvalidDataException("Invalid protected original identity");}
        byte[] IdentityAad(PackageHeader header,int ordinal){return Encoding.UTF8.GetBytes("MediaComplianceReviewer/package-identity/v1\n"+header.PackageId+"\n"+ordinal.ToString(CultureInfo.InvariantCulture));}
        internal void SealIdentity(PackageHeader header,int ordinal,VaultKey key){ValidateIdentity();IdentityIv=EvidenceFormat.Random(12);byte[] plain=Catalog.ReviewUtf8.GetBytes(PackageFormat.Json().Serialize(new PackageIdentity {GroupId=GroupId,Key=Key,Hash=Hash,CaptureId=CaptureId}));try{IdentityCipher=Convert.ToBase64String(Crypto.Encrypt(key,IdentityIv,IdentityAad(header,ordinal),plain));}finally{Array.Clear(plain,0,plain.Length);}ValidateShape();}
        internal void OpenIdentity(PackageHeader header,int ordinal,VaultKey key){byte[] plain=Crypto.Decrypt(key,IdentityIv,IdentityAad(header,ordinal),Convert.FromBase64String(IdentityCipher));try{var identity=PackageFormat.Json().Deserialize<PackageIdentity>(Catalog.ReviewUtf8.GetString(plain));if(identity==null)throw new InvalidDataException("Missing protected original identity");GroupId=identity.GroupId;Key=identity.Key;Hash=identity.Hash;CaptureId=identity.CaptureId;ValidateIdentity();}finally{Array.Clear(plain,0,plain.Length);}}
    }
    internal sealed class PackageIdentity {public long GroupId;public string Key,Hash,CaptureId;public PackageIdentity(){}}
    internal sealed class PackageFrame {internal long Offset,Length;internal byte[] Iv;}
    public sealed class PackageItem {
        public int Number {get;internal set;}public long Size {get;internal set;}public string Hash {get;internal set;}
        public override string ToString(){string length=Size<1024 ? Size+" bytes" : Size<1048576 ? (Size/1024.0).ToString("0.##",CultureInfo.InvariantCulture)+" KiB" : (Size/1048576.0).ToString("0.##",CultureInfo.InvariantCulture)+" MiB";return "Stored item "+Number+" — "+length;}
    }
    internal static class PackageFormat {
        internal static readonly byte[] Magic=Encoding.ASCII.GetBytes("MCREPKG1"),End=Encoding.ASCII.GetBytes("MCREND01"),SealText=Encoding.UTF8.GetBytes("MediaComplianceReviewer package seal v1");
        internal static JavaScriptSerializer Json(){return new JavaScriptSerializer {MaxJsonLength=65536,RecursionLimit=16};}
        internal static bool IsHash(string value){return value!=null && value.Length==64 && value.All(c=>c>='0' && c<='9' || c>='a' && c<='f');}
        internal static byte[] Aad(PackageHeader h,byte[] digest,long bytes){return Encoding.UTF8.GetBytes("MediaComplianceReviewer/package/v1\n"+h.PackageId+"\n"+h.WorkspaceId+"\n"+h.Count.ToString(CultureInfo.InvariantCulture)+"\n"+bytes.ToString(CultureInfo.InvariantCulture)+"\n"+EvidenceFormat.Hex(digest));}
        internal static byte[] Exact(Stream source,int count,CancellationToken token){var buffer=new byte[count];int at=0;while(at<count){token.ThrowIfCancellationRequested();int n=source.Read(buffer,at,count-at);if(n==0)throw new EndOfStreamException("Protected package is truncated");at+=n;}return buffer;}
        internal static T Object<T>(Stream source,int limit,CancellationToken token){int length=BitConverter.ToInt32(Exact(source,4,token),0);if(length<2 || length>limit)throw new InvalidDataException("Protected package JSON exceeds its bound");return Json().Deserialize<T>(Catalog.ReviewUtf8.GetString(Exact(source,length,token)));}
        internal static PackageFrame Frame(FileStream source,int kind,int index,long maximum,CancellationToken token){
            var header=Exact(source,25,token);long length=BitConverter.ToInt64(header,5);if(header[0]!=kind || BitConverter.ToInt32(header,1)!=index || length<16 || length>maximum || length>source.Length-source.Position)throw new InvalidDataException("Invalid, reordered or incomplete protected package frame");var iv=new byte[12];Buffer.BlockCopy(header,13,iv,0,12);var frame=new PackageFrame {Offset=source.Position,Length=length,Iv=iv};source.Position+=length;return frame;
        }
        internal sealed class Slice:Stream {
            readonly FileStream file;readonly long offset,length;readonly CancellationToken token;long position;
            internal Slice(FileStream file,PackageFrame frame,CancellationToken token){this.file=file;offset=frame.Offset;length=frame.Length;this.token=token;}
            public override int Read(byte[] b,int at,int count){token.ThrowIfCancellationRequested();file.Position=offset+position;int n=file.ReadAsync(b,at,(int)Math.Min(count,length-position),token).GetAwaiter().GetResult();position+=n;return n;}
            public override long Position{get{return position;}set{if(value<0 || value>length)throw new ArgumentOutOfRangeException("value");position=value;}}public override long Length{get{return length;}}public override bool CanRead{get{return true;}}public override bool CanSeek{get{return true;}}public override bool CanWrite{get{return false;}}
            public override long Seek(long n,SeekOrigin origin){Position=checked(n+(origin==SeekOrigin.Begin ? 0 : origin==SeekOrigin.Current ? position : length));return position;}public override void Flush(){}public override void SetLength(long n){throw new NotSupportedException();}public override void Write(byte[] b,int a,int n){throw new NotSupportedException();}
        }
        internal sealed class Writer:IDisposable {
            readonly FileStream file;readonly SHA256 hash=SHA256.Create();readonly CancellationToken token;
            internal Writer(FileStream file,CancellationToken token){this.file=file;this.token=token;}
            internal void Write(byte[] bytes){token.ThrowIfCancellationRequested();file.Write(bytes,0,bytes.Length);hash.TransformBlock(bytes,0,bytes.Length,bytes,0);}
            internal void Object(object value,int bound){byte[] bytes=Catalog.ReviewUtf8.GetBytes(Json().Serialize(value));if(bytes.Length>bound)throw new InvalidDataException("Protected package metadata exceeds its bound");Write(BitConverter.GetBytes(bytes.Length));Write(bytes);}
            internal void Frame(int kind,int index,byte[] iv,Stream source,Action<long> progress){if(iv==null || iv.Length!=12 || source.Length<16 || source.Length>8L*1024*1024*1024)throw new InvalidDataException("Invalid stored ciphertext frame");Write(new[]{(byte)kind});Write(BitConverter.GetBytes(index));Write(BitConverter.GetBytes(source.Length));Write(iv);var block=new byte[65536];long done=0;int n;while((n=source.Read(block,0,block.Length))>0){token.ThrowIfCancellationRequested();file.Write(block,0,n);hash.TransformBlock(block,0,n,block,0);done+=n;if(progress!=null)progress(n);}if(done!=source.Length)throw new InvalidDataException("Stored ciphertext changed during package export");}
            internal void Seal(PackageHeader header,VaultKey key){hash.TransformFinalBlock(new byte[0],0,0);long length=file.Position;byte[] digest=hash.Hash,iv=EvidenceFormat.Random(12),seal=Crypto.Encrypt(key,iv,Aad(header,digest,length),SealText);using(var writer=new BinaryWriter(file,Encoding.UTF8,true)){writer.Write(End);writer.Write(length);writer.Write(digest);writer.Write(iv);writer.Write(seal.Length);writer.Write(seal);writer.Flush();}file.Flush(true);}
            public void Dispose(){hash.Dispose();}
        }
    }
    public sealed class EvidencePackageReader:IDisposable {
        readonly FileStream file;readonly bool owns;readonly int owner=Thread.CurrentThread.ManagedThreadId;readonly string identity;readonly long modified,size;
        PackageHeader header;readonly List<PackageRecord> records=new List<PackageRecord>();long footer;byte[] digest,iv,seal;VaultKey key;
        EvidencePackageReader(FileStream file,bool owns,CancellationToken token){this.file=file;this.owns=owns;var stamp=FileAccessNative.Stamp(file);identity=stamp.Identity;modified=stamp.ModifiedTicks;size=stamp.Size;Parse(token);}
        public static EvidencePackageReader Open(string path,CancellationToken token,Action<long,long,string> progress){
            if(String.IsNullOrEmpty(path) || path.Length>32767)throw new ArgumentException("Choose a protected package");FileStream file=null;
            for(int attempt=0;;attempt++)try{token.ThrowIfCancellationRequested();file=new FileStream(Paths.Io(Paths.Source(path)),FileMode.Open,FileAccess.Read,FileShare.Read,65536,FileOptions.Asynchronous|FileOptions.SequentialScan);return new EvidencePackageReader(file,true,token);}catch(Exception error){if(file!=null){file.Dispose();file=null;}if(error is OperationCanceledException || !FileAccessNative.Transient(error) || attempt>=3)throw;if(progress!=null)progress(attempt+1,3,"package open retries: "+error.Message);if(token.WaitHandle.WaitOne(attempt==0 ? 250 : attempt==1 ? 1000 : 3000))token.ThrowIfCancellationRequested();}
        }
        void Own(){if(Thread.CurrentThread.ManagedThreadId!=owner)throw new InvalidOperationException("Protected package reader belongs to its worker");}
        void Stable(){Own();var stamp=FileAccessNative.Stamp(file);if(stamp.Identity!=identity || stamp.ModifiedTicks!=modified || stamp.Size!=size)throw new InvalidDataException("Protected package changed while open");}
        void Parse(CancellationToken token){
            if(size<100 || size>2L*1024*1024*1024*1024)throw new InvalidDataException("Protected package length exceeds its bound");file.Position=0;if(!PackageFormat.Exact(file,8,token).SequenceEqual(PackageFormat.Magic))throw new InvalidDataException("This is not a supported protected Evidence package");header=PackageFormat.Object<PackageHeader>(file,65536,token);if(header==null)throw new InvalidDataException("Missing protected package header");header.Validate();long frames=0;
            for(int ordinal=0;ordinal<header.Count;ordinal++){var record=PackageFormat.Object<PackageRecord>(file,65536,token);if(record==null)throw new InvalidDataException("Missing protected original descriptor");record.ValidateShape();if(record.Version!=1){record.Metadata=PackageFormat.Frame(file,1,-1,1024L*1024*1024+16,token);if(record.Preview)record.Poster=PackageFormat.Frame(file,2,-1,1024L*1024*1024+16,token);}record.FirstChunk=file.Position;for(int index=0;index<record.ChunkCount;index++){if(++frames>300000)throw new InvalidDataException("Too many package frames; export a smaller selection");PackageFormat.Frame(file,3,index,record.Version==1 ? 8L*1024*1024*1024 : record.ChunkSize+16L,token);}records.Add(record);}
            footer=file.Position;if(!PackageFormat.Exact(file,8,token).SequenceEqual(PackageFormat.End) || BitConverter.ToInt64(PackageFormat.Exact(file,8,token),0)!=footer)throw new InvalidDataException("Protected package count or footer is invalid");digest=PackageFormat.Exact(file,32,token);iv=PackageFormat.Exact(file,12,token);int length=BitConverter.ToInt32(PackageFormat.Exact(file,4,token),0);if(length<16 || length>128 || length!=file.Length-file.Position)throw new InvalidDataException("Protected package seal is truncated or has trailing data");seal=PackageFormat.Exact(file,length,token);
        }
        void Authenticate(VaultKey candidate,CancellationToken token,Action<long,long,string> progress){
            Stable();file.Position=0;using(var hash=SHA256.Create()){byte[] block=new byte[1024*1024];long done=0;while(done<footer){token.ThrowIfCancellationRequested();int n=file.ReadAsync(block,0,(int)Math.Min(block.Length,footer-done),token).GetAwaiter().GetResult();if(n==0)throw new EndOfStreamException("Protected package is truncated");hash.TransformBlock(block,0,n,block,0);done+=n;if(progress!=null)progress(done,footer,"package bytes authenticated");}hash.TransformFinalBlock(new byte[0],0,0);if(!hash.Hash.SequenceEqual(digest))throw new InvalidDataException("Protected package contents, order or metadata changed");}
            byte[] check=Crypto.Decrypt(candidate,iv,PackageFormat.Aad(header,digest,footer),seal);try{if(!check.SequenceEqual(PackageFormat.SealText))throw new CryptographicException("Protected package authentication failed");}finally{Array.Clear(check,0,check.Length);}token.ThrowIfCancellationRequested();Stable();
        }
        public bool Unlocked{get{return key!=null;}}
        public PackageItem[] Items{get{Own();if(key==null)return new PackageItem[0];return records.Select((r,i)=>new PackageItem {Number=i+1,Size=r.Size,Hash=r.Hash}).ToArray();}}
        public void Unlock(byte[] password,CancellationToken token,Action<long,long,string> progress){Own();Lock();VaultKey candidate=null;try{if(password==null || password.Length<1 || password.Length>65536)throw new ArgumentException("Enter a bounded non-empty password");if(progress!=null)progress(0,1,"password key derivation");candidate=header.Vault.Open(header.WorkspaceId,password,token);Authenticate(candidate,token,progress);for(int i=0;i<records.Count;i++){token.ThrowIfCancellationRequested();records[i].OpenIdentity(header,i,candidate);}key=candidate;candidate=null;}finally{if(candidate!=null)candidate.Dispose();if(key==null)ClearIdentities();if(password!=null)Array.Clear(password,0,password.Length);}}
        void ClearIdentities(){foreach(var record in records){record.GroupId=0;record.Key=null;record.Hash=null;record.CaptureId=null;}}
        public void Lock(){Own();if(key!=null){key.Dispose();key=null;}ClearIdentities();}
        PackageRecord Record(int index,CancellationToken token){Stable();token.ThrowIfCancellationRequested();if(key==null)throw new InvalidOperationException("Unlock the protected package first");if(index<0 || index>=records.Count)throw new ArgumentOutOfRangeException("index");return records[index];}
        byte[] Field(PackageRecord record,PackageFrame frame,string purpose,CancellationToken token,int limit){using(var sink=new EvidenceFormat.CappedSink(limit)){Crypto.DecryptVerifiedStream(key,()=>new PackageFormat.Slice(file,frame,token),frame.Iv,EvidenceFormat.Aad(header.WorkspaceId,record.Key,record.Hash,purpose,record.Version,record.CaptureId,record.Size,record.ChunkCount),sink,token);return sink.Result();}}
        EvidenceInspection ReadOriginal(int index,Stream output,CancellationToken token,Action<long,long,string> progress){
            var record=Record(index,token);var result=new EvidenceInspection {GroupId=record.GroupId,Hash=record.Hash,Size=record.Size};try{
                if(record.Version!=1){result.Metadata=Field(record,record.Metadata,"metadata",token,1024*1024);if(record.Poster!=null)result.Preview=Field(record,record.Poster,"preview",token,32768);if(record.Version==3){var metadata=EvidenceFormat.Json().Deserialize<Dictionary<string,object>>(Catalog.ReviewUtf8.GetString(result.Metadata));if(Convert.ToInt64(metadata["groupId"])!=record.GroupId || (string)metadata["captureId"]!=record.CaptureId || (string)metadata["decisionKey"]!=record.Key || Convert.ToInt64(metadata["originalSize"])!=record.Size || Convert.ToInt32(metadata["chunkCount"])!=record.ChunkCount || Convert.ToInt32(metadata["chunkSize"])!=record.ChunkSize || (string)((Dictionary<string,object>)metadata["hashes"])["fullSha256"]!=record.Hash)throw new InvalidDataException("Authenticated original metadata disagrees with the package descriptor");}}
                file.Position=record.FirstChunk;
                if(record.Version==1){var frame=PackageFormat.Frame(file,3,0,8L*1024*1024*1024,token);using(var sink=new EvidenceFormat.LegacySink(frame.Length-16,output)){Crypto.DecryptVerifiedStream(key,()=>new PackageFormat.Slice(file,frame,token),frame.Iv,EvidenceFormat.Aad(header.WorkspaceId,record.Key,record.Hash,null,1,null,0,0),sink,token);sink.Complete();if(sink.Original.Count!=record.Size || sink.Original.Finish()!=record.Hash)throw new InvalidDataException("Legacy package original full SHA-256 or size disagrees");result.Metadata=sink.Metadata.Result();if(progress!=null)progress(record.Size,record.Size,"legacy original bytes authenticated");}}
                else using(var sink=new EvidenceFormat.HashSink(output)){for(int chunk=0;chunk<record.ChunkCount;chunk++){var frame=PackageFormat.Frame(file,3,chunk,record.ChunkSize+16L,token);long next=file.Position;if(frame.Length-16!=Math.Min(record.ChunkSize,record.Size-sink.Count))throw new InvalidDataException("Protected original chunk length disagrees");Crypto.DecryptVerifiedStream(key,()=>new PackageFormat.Slice(file,frame,token),frame.Iv,EvidenceFormat.Aad(header.WorkspaceId,record.Key,record.Hash,"chunk",record.Version,record.CaptureId,record.Size,record.ChunkCount,chunk),sink,token);file.Position=next;if(progress!=null)progress(sink.Count,record.Size,"original bytes authenticated");}if(sink.Count!=record.Size || sink.Finish()!=record.Hash)throw new InvalidDataException("Package original full SHA-256 or size disagrees");}
                token.ThrowIfCancellationRequested();Stable();result.Verified=true;return result;
            }catch{result.Dispose();throw;}
        }
        public EvidenceInspection Inspect(int index,CancellationToken token,Action<long,long,string> progress){return ReadOriginal(index,null,token,progress);}
        public void ExportOriginal(int index,string destination,CancellationToken token,Action<long,long,string> progress){
            Record(index,token);var options=new ReportOptions {Destination=destination};options.Validate();string target=options.Destination;if(File.Exists(Paths.Io(target)) || Directory.Exists(Paths.Io(target)))throw new IOException("Original destination already exists; choose a new file");
            // Authenticate before creating the only allowed plaintext file: the explicit destination.
            using(var verified=ReadOriginal(index,null,token,progress)){}bool created=false;string identity=null;
            try{using(var output=new FileStream(Paths.Io(target),FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None,65536,FileOptions.Asynchronous|FileOptions.SequentialScan)){created=true;identity=FileAccessNative.Stamp(output).Identity;using(var original=ReadOriginal(index,output,token,progress)){}output.Flush(true);ReviewerEngine.VerifyExportFile(output,records[index].Hash,records[index].Size,token,progress??((d,t,u)=>{}));token.ThrowIfCancellationRequested();Stable();}}
            catch(Exception error){if(created){bool removed=false;try{removed=FileAccessNative.DeleteOwnedFile(target,identity);}catch(IOException){}catch(UnauthorizedAccessException){}if(!removed)throw new IncompleteOriginalExportException(target,error);}throw;}
        }
        internal static void VerifyWritten(FileStream file,VaultKey key,CancellationToken token,Action<long,long,string> progress){using(var reader=new EvidencePackageReader(file,false,token)){reader.Authenticate(key,token,progress);for(int i=0;i<reader.records.Count;i++){token.ThrowIfCancellationRequested();reader.records[i].OpenIdentity(reader.header,i,key);}}}
        internal void Reconcile(VaultKey key,string operation,string payload,CancellationToken token,Action<long,long,string> progress){if(header.OperationId!=operation || header.PayloadHash!=payload)throw new IOException("Package destination already exists for a different operation");Authenticate(key,token,progress);}
        public void Dispose(){Own();Lock();if(owns)file.Dispose();}
    }
    public sealed partial class ReviewerEngine {
        public string RequestEvidencePackageExport(long[] groupIds,string destination,string operationId){
            if(groupIds==null || groupIds.Length<1 || groupIds.Length>200 || groupIds.Any(x=>x<=0) || String.IsNullOrEmpty(operationId) || operationId.Length>100)throw new ArgumentException("Select one through 200 retained Non-compliant or Evidence items");var ids=groupIds.Distinct().OrderBy(x=>x).ToArray();var options=new ReportOptions {Destination=destination};options.Validate();long epoch=VaultGeneration;if(!VaultUnlocked)throw new InvalidOperationException("Unlock stored originals before exporting a protected package");
            lock(scanGate){if(reportActive || scan!=null && !scan.Finished || sourceConnectionBusy)throw new InvalidOperationException("Finish or cancel the current scan/export/source task first");reportActive=true;try{return EnqueueOperation("EvidencePackageExport",(db,t,p)=>ExportEvidencePackage(db,ids,options,operationId,epoch,t,p),4096+ids.Length*8+destination.Length*2L,()=>{lock(scanGate)reportActive=false;});}catch{reportActive=false;throw;}}
        }
        OriginalReceipt ExportEvidencePackage(SqliteConnection db,long[] ids,ReportOptions options,string operation,long epoch,CancellationToken token,Action<long,long,string> progress){
            RequireVault(epoch,token);string workspace=EvidenceFormat.Workspace(db),payload=Identity.Digest("evidence-package/v1\n"+workspace+"\n"+options.Destination+"\n"+String.Join(",",ids));object priorPayload=db.Scalar("SELECT payload_hash FROM operations WHERE id=?",operation);if(priorPayload!=null && (string)priorPayload!=payload)throw new InvalidOperationException("Operation identifier has a different export payload");
            if(File.Exists(Paths.Io(options.Destination))){using(var prior=EvidencePackageReader.Open(options.Destination,token,progress))prior.Reconcile(vaultKey,operation,payload,token,progress);return new OriginalReceipt {Kind="EvidencePackageExport",OperationId=operation,Reconciled=true,OutputPublished=true,Message="Previously published protected package verified: "+options.Destination};}
            if(priorPayload!=null)throw new IOException("This package operation already completed, but its destination is missing. Choose a new operation instead of replaying the write");
            long revision=(long)WaitWrite(w=>(object)Catalog.Revision(w));var header=new PackageHeader {Version=1,Count=ids.Length,PackageId=Guid.NewGuid().ToString("N"),WorkspaceId=workspace,OperationId=operation,PayloadHash=payload,CreatedUtc=Catalog.Now(),Vault=VaultDescriptor.Read(db)};header.Validate();
            using(var output=new ReportOutput(options)){WaitWrite(w=>{Catalog.Log(w,"info","Evidence package",options.Destination,"Writing incomplete protected package: "+output.Partial);return null;});
                try{using(var file=output.Open("package")){using(var writer=new PackageFormat.Writer(file,token)){writer.Write(PackageFormat.Magic);writer.Object(header,65536);long copied=0;int ordinal=0;
                    foreach(long group in ids){RequireVault(epoch,token);CheckReportRevision(db,revision);if(db.Scalar("SELECT 1 FROM review_groups WHERE id=? AND retired=0 AND status IN('NON_COMPLIANT','EVIDENCE')",group)==null)throw new InvalidOperationException("A selected item is no longer a current Non-compliant or Evidence review");using(var verified=ReadOriginal(db,group,epoch,token,progress,null)){
                        string capture=db.Scalar("SELECT capture_id FROM original_links WHERE group_id=?",group) as string;PackageRecord record;long row;
                        if(capture!=null){var r=db.Query("SELECT rowid,decision_key,chunk_count,preview_iv FROM original_captures WHERE id=? AND state='complete'",new object[]{capture},1)[0];row=(long)r[0];record=new PackageRecord {GroupId=group,Size=verified.Size,Version=3,ChunkSize=EvidenceFormat.ChunkSize,ChunkCount=checked((int)(long)r[2]),Key=(string)r[1],Hash=verified.Hash,CaptureId=capture,Preview=r[3]!=null};}
                        else{var manifest=db.Query("SELECT rowid,chunk_size,chunk_count,preview_iv FROM evidence_manifests WHERE decision_key=?",new object[]{verified.LegacyKey},1);if(manifest.Count!=0){row=(long)manifest[0][0];record=new PackageRecord {GroupId=group,Size=verified.Size,Version=2,ChunkSize=checked((int)(long)manifest[0][1]),ChunkCount=checked((int)(long)manifest[0][2]),Key=verified.LegacyKey,Hash=verified.Hash,Preview=manifest[0][3]!=null};}else{row=(long)db.Scalar("SELECT rowid FROM evidence_items WHERE decision_key=?",verified.LegacyKey);record=new PackageRecord {GroupId=group,Size=verified.Size,Version=1,ChunkCount=1,Key=verified.LegacyKey,Hash=verified.Hash};}}
                        record.SealIdentity(header,ordinal++,vaultKey);writer.Object(record,65536);Action<long> count=n=>{copied+=n;RequireVault(epoch,token);progress(copied,-1,"encrypted package bytes copied");};
                        if(record.Version!=1){string table=record.Version==3 ? "original_captures" : "evidence_manifests";WritePackageField(db,writer,table,row,"metadata_ciphertext","metadata_iv",1,-1,token,count);if(record.Preview)WritePackageField(db,writer,table,row,"preview_ciphertext","preview_iv",2,-1,token,count);}
                        for(int chunk=0;chunk<record.ChunkCount;chunk++){RequireVault(epoch,token);if(record.Version==1)WritePackageField(db,writer,"evidence_items",row,"ciphertext","iv",3,0,token,count);else{string table=record.Version==3 ? "original_chunks" : "evidence_chunks";long chunkRow=(long)db.Scalar("SELECT rowid FROM "+table+" WHERE "+(record.Version==3 ? "capture_id" : "decision_key")+"=? AND chunk_index=?",record.Version==3 ? capture : record.Key,chunk);WritePackageField(db,writer,table,chunkRow,"ciphertext","iv",3,chunk,token,count);}}
                    }}RequireVault(epoch,token);CheckReportRevision(db,revision);writer.Seal(header,vaultKey);}
                    EvidencePackageReader.VerifyWritten(file,vaultKey,token,progress);
                }RequireVault(epoch,token);output.Publish();var result=new OriginalReceipt {Kind="EvidencePackageExport",OperationId=operation,OutputPublished=true,Message="Protected package exported: "+options.Destination};try{WaitWrite(w=>{w.Execute("INSERT INTO operations VALUES(?,?,?,?)",operation,payload,Catalog.Now(),Catalog.Revision(w));Catalog.Log(w,"info","Evidence package",options.Destination,"Completed protected package: "+ids.Length+" originals.");return null;});}catch(Exception error){result.Message+=" The completion status could not be saved: "+error.Message;}return result;
                }catch(Exception error){try{WaitWrite(w=>{Catalog.Log(w,"error","Evidence package",options.Destination,"Stopped package; incomplete output: "+output.Partial+". "+error.Message);return null;});}catch{}throw;}
            }
        }
        static void WritePackageField(SqliteConnection db,PackageFormat.Writer writer,string table,long row,string column,string ivColumn,int kind,int index,CancellationToken token,Action<long> progress){token.ThrowIfCancellationRequested();using(var source=ImportedFields.Open(db,table,row,column)){var iv=db.Scalar("SELECT "+ivColumn+" FROM "+table+" WHERE rowid=?",row) as byte[];writer.Frame(kind,index,iv,source,progress);}}
    }
}
